"""A small memoize decorator with hit/miss counters."""
import functools
import inspect


def _canonical_key(fn, args, kwargs):
    """Build a hashable key for a call, or return None if uncacheable."""
    try:
        sig = inspect.signature(fn)
        bound = sig.bind(*args, **kwargs)
        bound.apply_defaults()
        items = sorted(bound.arguments.items())
        key = tuple((name, value) for name, value in items)
        hash(key)  # ensure hashable
        return key
    except (TypeError, ValueError, AttributeError):
        # Unhashable argument values, or fn has no introspectable signature —
        # the call cannot be cached safely.
        return None


def memoize(fn):
    cache = {}
    stats = {"hits": 0, "misses": 0}

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        key = _canonical_key(fn, args, kwargs)
        if key is not None and key in cache:
            stats["hits"] += 1
            return cache[key]
        result = fn(*args, **kwargs)
        if key is not None:
            stats["misses"] += 1
            cache[key] = result
        return result

    wrapper.cache_info = lambda: dict(stats, size=len(cache))

    def cache_clear():
        cache.clear()
        stats.update(hits=0, misses=0)

    wrapper.cache_clear = cache_clear
    return wrapper
